"""Offline planning estimates from archived observations; no current quotes or API calls."""
import collections, hashlib, json, statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).resolve().parents[1]/'delivery'
def load(p):return json.loads((ROOT/p).read_text())
def save(n,x):(OUT/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
s=load('dev24-c-v82-20261117/delivery/summary.json')
ab=load('dev24-completion-20261117-v5/delivery/summary.json')
rows=load('dev24-c-v82-20261117/delivery/ABC-per-task.json')
scale=50/24
arm_estimates={a:{'historical_tasks':24,'planning_tasks':50,'tokens_linear_proxy':v['totals']['total_tokens']*scale,'historical_mixed_price_cost_linear_proxy_cny':v['totals']['metered_cny']*scale,'peak_no_cache_at_historical_token_volume_cny':v['totals']['upper_cny']*scale,'stage_hours_linear_proxy':v['wall_seconds_excluding_images_including_locator_harness']*scale/3600} for a,v in s['arms'].items()}
c_peak=sum(r['total_cost']['peak_cache_adjusted_cny'] for r in rows if r['arm']=='C')
peak_same_cache=(ab['all_trial_peak_cache_adjusted_cny']+c_peak)*scale
groups=collections.defaultdict(list); imgs=[]
for p in (ROOT/'dev24-c-v82-20261117/evidence/run/images').glob('*/image.json'):
    x=json.loads(p.read_text());imgs.append(x);groups[p.parent.name.rsplit('-',1)[0].replace('__','/')].append(x['size_bytes']/2**30)
repo_counts=load('freezes/holdout-v1/manifest.json')['repository_counts']
known=sum(statistics.mean(groups[r])*n for r,n in repo_counts.items() if r in groups)
missing={r:n for r,n in repo_counts.items() if r not in groups}
all_sizes=[v for vs in groups.values() for v in vs]
low=known+sum(missing.values())*min(all_sizes);high=known+sum(missing.values())*max(all_sizes)
save('estimates.json',{'basis':'Archived dev24 observations and historical price quotation only; offline, no current price/account/disk query. Planning ranges are assumptions, not confidence intervals or fees caps.', 'arms':arm_estimates, 'API':{'historical_mixed_price_linear_proxy_cny':sum(x['historical_mixed_price_cost_linear_proxy_cny'] for x in arm_estimates.values()),'same_cache_all_offpeak_cny':peak_same_cache/2,'same_cache_all_peak_cny':peak_same_cache,'peak_no_cache_at_historical_tokens_cny':sum(x['peak_no_cache_at_historical_token_volume_cny'] for x in arm_estimates.values()),'ordinary_planning_range_cny':[10,25],'nominal_full_token_budget_peak_no_cache_cny':150*(1000000*2+64000*8)/1e6+100*(128000*2+8192*8)/1e6,'full_budget_amount_caveat':'Arithmetic stress scenario using configured token budgets; not a billing guarantee or financial stopping gate.','max_coding_calls':6000,'max_locator_calls':400,'total_financial_cap':None,'prices_snapshot_cny_per_million':{'input_cache_hit_peak':0.04,'input_cache_miss_peak':2,'output_peak':8,'offpeak_multiplier':0.5}},'time':{'stage_linear_proxy_hours':sum(x['stage_hours_linear_proxy'] for x in arm_estimates.values()),'planning_stage_hours':[5.5,8],'new_image_download_decompression_hours_assumption':[0.5,2],'boot_environment_transfer_cleanup_hours_assumption':[0.5,1],'total_planning_hours':[6.5,11],'C_historical_stage_seconds':s['arms']['C']['wall_seconds_excluding_images_including_locator_harness'],'C_historical_image_seconds':s['C_image_pull_seconds'],'C_historical_other_including_budget_handoff_seconds':s['C_run_wall_seconds']-s['arms']['C']['wall_seconds_excluding_images_including_locator_harness']-s['C_image_pull_seconds'],'C_other_not_scaled_into_new_run':True,'timeout_risk':'Long tests/provider delays can exceed planning range; no total time cap imposed.'},'cloud':{'archived_running_compute_plus_150GiB_disk_cny_per_hour':4.09,'planning_running_cost_cny':[6.5*4.09,11*4.09],'archived_public_egress_cny_per_GB':0.67,'egress_volume':'not_measured_not_estimated','stopped_disk_retention_fee':'not_estimated_current_disk_unit_quote_unavailable','combined_ordinary_API_and_running_cloud_cny':[10+6.5*4.09,25+11*4.09],'current_quote_checked':False},'disk':{'disk_capacity_archived_GiB':150,'last_measured_free_bytes':95961354240,'last_measurement_scope':'Before dev24 C(v8.2), with 18 task images cached; not a shutdown/current measurement.','last_measured_free_GiB':95961354240/2**30,'six_subsequent_images_logical_sum_GiB':sum(x['size_bytes'] for x in imgs if not x['preexisting'])/2**30,'dev24_24_images_logical_sum_GiB':sum(all_sizes),'dev24_image_logical_size_range_GiB':[min(all_sizes),max(all_sizes)],'holdout_repository_counts':repo_counts,'dev24_sizes_by_repository_GiB':dict(groups),'unrepresented_holdout_repositories':missing,'50_images_repository_weighted_logical_proxy_GiB':[low,high],'50_images_planning_increment_GiB':[50,90],'working_reserve_GiB':25,'free_space_planning_requirement_GiB':[75,115],'assessment':'Capacity not cleared. Upper planning requirement exceeds even the last measured free space. Full 50-image retention cannot be guaranteed on the existing disk. No automatic expansion or cache deletion.','caveat':'Docker Size is logical uncompressed size, not unique layer disk consumption. Missing per-image manifests/layer inventory, version differences, decompression temporaries, logs, and current df prevent exact prediction.','alternative_for_user_review':'Preserve the old 24 cached images; optionally remove only each new holdout task image after its A/B/C evaluation and evidence collection. This policy is not authorized or implemented.'}})
ids=(ROOT/'freezes/holdout-v1/ids.txt').read_text().splitlines()
save('execution-order.json',{'status':'preflight_only_not_authorized_to_boot','ids_sha256':hashlib.sha256((ROOT/'freezes/holdout-v1/ids.txt').read_bytes()).hexdigest(),'repetitions':1,'concurrency':1,'tasks':[{'number':i+1,'instance_id':v,'arm_order':[['A','B','C'],['B','C','A'],['C','A','B']][i%3]} for i,v in enumerate(ids)],'completed_stages':[],'holdout_unblinded':False,'model_API_calls':0})
print(json.dumps({'arm_estimates':arm_estimates,'same_cache_peak_cny':peak_same_cache,'image_proxy_GiB':[low,high]},ensure_ascii=False))
